#!/usr/bin/env python
# FIXED FILE: do not edit. Generated by bin/adding_method/add_method.py.
#
# Does all the file work for a Python method and calls the three functions of
# <method>_core.py. Usage: messi_run.py <step> --method=NAME [--key=value ...]
# Steps: preprocess, train, predict, select_feature, check.

import sys

# Keep the module folder free of __pycache__: Nextflow hashes it for -resume.
sys.dont_write_bytecode = True

import argparse
import glob
import os
import pickle
import random
import shutil
import tempfile
import traceback

try:
    import numpy as np
    import pandas as pd
    import messi_contract as contract
except ImportError as error:
    sys.exit(
        "ERROR: {}. The MESSI wrappers need numpy and pandas: install them, or run "
        "this inside the method's container.".format(error)
    )


def save(obj, path):
    with open(path, "wb") as handle:
        pickle.dump(obj, handle)


def load(path):
    with open(path, "rb") as handle:
        return pickle.load(handle)


def set_seed(seed):
    random.seed(seed)
    np.random.seed(seed)


# ---- MuData to plain data (only these two steps need mudata) ----


def read_mudata(path):
    import mudata

    return mudata.read(path)


def response_to_binary(values):
    labels = pd.Series(values).astype(str).str.strip().str.lower()
    mapping = {"yes": 1, "y": 1, "1": 1, "true": 1, "no": 0, "n": 0, "0": 0, "false": 0}
    bad = sorted(set(labels) - set(mapping))
    if bad:
        contract.contract_fail("the response column of the data", ", ".join(bad), "yes/no or 1/0 labels")
    return labels.map(mapping).values.astype(int)


def mudata_to_plain(mdata):
    X = {}
    for view in mdata.mod.keys():
        adata = mdata.mod[view]
        matrix = adata.X.toarray() if hasattr(adata.X, "toarray") else np.asarray(adata.X)
        X[view] = pd.DataFrame(matrix, index=[str(s) for s in adata.obs_names], columns=list(adata.var_names))
    first_view = next(iter(mdata.mod.keys()))
    data = {"X": X, "y": response_to_binary(mdata.mod[first_view].obs["response"].values)}
    return contract.validate_plain_data(data, "the data loaded from the MuData")


def load_test_splits(split_dir):
    files = sorted(glob.glob(os.path.join(split_dir, "*.txt")))
    if not files:
        sys.exit("ERROR: no .txt fold files in {}".format(split_dir))
    return {
        os.path.splitext(os.path.basename(f))[0]: np.atleast_1d(np.loadtxt(f).astype(int)) for f in files
    }


def step_preprocess(opts):
    mdata = read_mudata(opts.data_path)
    splits = load_test_splits(opts.split_dir)
    for fold, test_idx in splits.items():
        train_idx = sorted(int(i) for other, idx in splits.items() if other != fold for i in idx)
        os.makedirs(fold, exist_ok=True)
        save(mudata_to_plain(mdata[train_idx].copy()), os.path.join(fold, "train.pkl"))
        save(mudata_to_plain(mdata[test_idx].copy()), os.path.join(fold, "test.pkl"))
        print("Prepared {} with {} test samples".format(fold, len(test_idx)))


# ---- The steps that call the developer's functions ----


def step_train(opts):
    core = contract.load_core(opts.method)
    train = load(os.path.join(opts.fold_path, "train.pkl"))
    test = load(os.path.join(opts.fold_path, "test.pkl"))
    seed = contract.seed_from_label(opts.seed_label)
    set_seed(seed)
    print("Calling fit() on {} samples, seed {}".format(len(train["y"]), seed))
    model = contract.validate_model(core.fit(train["X"], train["y"], seed=seed))
    save(model, opts.model_out)
    save(test, opts.test_out)


def step_predict(opts):
    core = contract.load_core(opts.method)
    model = load(opts.model_path)
    test = load(opts.test_path)
    samples = list(next(iter(test["X"].values())).index)
    print("Calling predict_proba() on {} samples".format(len(samples)))
    phat = contract.validate_predictions(core.predict_proba(model, test["X"]), samples)
    table = contract.build_result_table(phat, samples, test["y"], opts.method, opts.dataset, opts.fold)
    contract.write_result_csv(table, opts.result_out)


def step_select_feature(opts):
    core = contract.load_core(opts.method)
    data = mudata_to_plain(read_mudata(opts.data_path))
    seed = contract.seed_from_label(opts.dataset)
    set_seed(seed)
    print("Calling fit() on all {} samples, seed {}".format(len(data["y"]), seed))
    model = contract.validate_model(core.fit(data["X"], data["y"], seed=seed))
    features = contract.validate_features(core.feature_weights(model), data["X"])
    contract.write_feature_csv(contract.build_feature_table(features, opts.method, opts.dataset), opts.features_out)
    record = contract.build_hyperparameter_record(
        getattr(core, "HYPERPARAMETERS", None), opts.method, opts.dataset, seed
    )
    contract.write_hyperparameter_json(record, opts.hyperparameters_out)


# ---- Self-check on synthetic data, used by `add_method.py check` ----


def synthetic_data(n, seed):
    rng = np.random.RandomState(seed)
    samples = ["sample_{:03d}".format(i + 1) for i in range(n)]
    y = np.array([(i + 1) % 2 == 0 for i in range(n)], dtype=int)

    def make_view(p, prefix):
        values = rng.normal(size=(n, p))
        values[:, :3] += 2 * y[:, None]
        return pd.DataFrame(values, index=samples, columns=["{}_{:02d}".format(prefix, j + 1) for j in range(p)])

    return {"view_a": make_view(12, "a"), "view_b": make_view(8, "b")}, y


def auc(y, score):
    ranks = pd.Series(score).rank().values
    n1, n0 = int((y == 1).sum()), int((y == 0).sum())
    return (ranks[y == 1].sum() - n1 * (n1 + 1) / 2) / (n1 * n0)


def report(status, name, detail, fix=None):
    print("  {:<4} {:<16} {}".format(status, name, detail.replace("\n", "\n       ")))
    if fix:
        print("       {:<16} Fix: {}".format("", fix))


def fix_hint(error):
    if isinstance(error, ImportError):
        return "Install the package, or use a container that has it."
    if isinstance(error, NotImplementedError):
        return "Fill in this function in the core file."
    return "Fix this function in the core file. The message above says what it returned and what is expected."


def error_text(error):
    if isinstance(error, (contract.ContractError, NotImplementedError)):
        return str(error)
    last = traceback.extract_tb(error.__traceback__)[-1]
    return "{}: {} (at {}, line {})".format(type(error).__name__, error, os.path.basename(last.filename), last.lineno)


def report_home_packages():
    if os.environ.get("MESSI_CHECK_IMAGE") != "1":
        return
    under_home = set()
    for name, module in list(sys.modules.items()):
        path = getattr(module, "__file__", None)
        if path and (path.startswith("/home/") or path.startswith("/root/")) and "/tmp/" not in path:
            under_home.add(name.split(".")[0])
    if under_home:
        print("HOME-PACKAGES: " + ",".join(sorted(under_home)))


def step_check(opts):
    core_file = opts.method + "_core.py"
    print("Self-check of '{}' on synthetic data (2 views, 40 train and 12 test samples)".format(opts.method))
    failed = False

    def run(name, function):
        nonlocal failed
        try:
            return True, function()
        except Exception as error:  # the developer's code can raise anything
            report("FAIL", name, error_text(error), fix_hint(error))
            failed = True
            return False, None

    loaded, core = run(core_file, lambda: contract.load_core(opts.method))
    if not loaded:
        print("Result: FAIL")
        return 1

    X, y = synthetic_data(52, 1)
    X_train = {view: frame.iloc[:40] for view, frame in X.items()}
    X_test = {view: frame.iloc[40:] for view, frame in X.items()}
    y_train, y_test = y[:40], y[40:]
    samples = list(next(iter(X_test.values())).index)
    workdir = tempfile.mkdtemp(prefix="messi_check")
    try:
        set_seed(1)

        def fit_and_reload():
            model = contract.validate_model(core.fit(X_train, y_train, seed=1))
            save(model, os.path.join(workdir, "model.pkl"))
            return load(os.path.join(workdir, "model.pkl"))

        fitted, model = run("fit", fit_and_reload)
        if fitted:
            report("PASS", "fit", "returned {}, saved and reloaded with pickle".format(contract.describe(model)))
            predicted, phat = run(
                "predict_proba",
                lambda: contract.validate_predictions(core.predict_proba(model, X_test), samples),
            )
            if predicted:
                score = auc(y_test, phat)
                report(
                    "PASS",
                    "predict_proba",
                    "{} scores from {:.3f} to {:.3f}, AUC on synthetic data {:.2f}".format(
                        len(samples), phat.min(), phat.max(), score
                    ),
                )
                if score < 0.5:
                    print("       Note: AUC below 0.5. Check that the score is the probability of class 1.")
            weighted, features = run(
                "feature_weights",
                lambda: contract.validate_features(core.feature_weights(model), X_train),
            )
            if weighted:
                report(
                    "PASS",
                    "feature_weights",
                    "{} rows in views: {}".format(len(features), ", ".join(features["view"].unique())),
                )
            if predicted and weighted:

                def write_all():
                    result = contract.build_result_table(phat, samples, y_test, opts.method, "synthetic", "fold_1")
                    contract.write_result_csv(result, os.path.join(workdir, "result.csv"))
                    table = contract.build_feature_table(features, opts.method, "synthetic")
                    contract.write_feature_csv(table, os.path.join(workdir, "features.csv"))
                    record = contract.build_hyperparameter_record(
                        getattr(core, "HYPERPARAMETERS", None), opts.method, "synthetic", 1
                    )
                    contract.write_hyperparameter_json(record, os.path.join(workdir, "hyperparameters.json"))

                written, _ = run("output files", write_all)
                if written:
                    report("PASS", "output files", "result table, feature table and hyperparameter JSON were written")
        else:
            report("SKIP", "predict_proba", "needs a working fit()")
            report("SKIP", "feature_weights", "needs a working fit()")
    finally:
        shutil.rmtree(workdir, ignore_errors=True)
    report_home_packages()
    print("Result: FAIL" if failed else "Result: PASS")
    return 1 if failed else 0


def main():
    parser = argparse.ArgumentParser(description="Fixed wrapper of a MESSI Python method.")
    parser.add_argument("step", choices=["preprocess", "train", "predict", "select_feature", "check"])
    for option in (
        "method data_path split_dir fold_path seed_label model_out test_out model_path "
        "test_path dataset fold result_out features_out hyperparameters_out"
    ).split():
        parser.add_argument("--" + option)
    opts = parser.parse_args()
    if opts.step == "check":
        return step_check(opts)
    steps = {
        "preprocess": step_preprocess,
        "train": step_train,
        "predict": step_predict,
        "select_feature": step_select_feature,
    }
    try:
        steps[opts.step](opts)
    except (contract.ContractError, NotImplementedError) as error:
        print(str(error), file=sys.stderr)
        return 1
    print("Done")
    return 0


if __name__ == "__main__":
    sys.exit(main())
